# pylint: disable=C0301,W0613
"""
coverage test for autocell, deployed on jn-cell08
mode: routine commit local
trigger by jenkins
"""

import os
import sys
import logging
from abc import ABC, abstractmethod

# 配置日志
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

MODE = os.environ.get("MODE", "routine")


class BaseCoverageJob(ABC):
    """Coverage 任务基类"""

    def __init__(self):
        self.mode = MODE

    @abstractmethod
    def execute(self):
        """执行 coverage 任务"""
        pass

    def log_info(self, message):
        """记录信息日志"""
        logger.info(f"[{self.mode}] {message}")

    def log_error(self, message):
        """记录错误日志"""
        logger.error(f"[{self.mode}] {message}")


class BaseSummaryJob(ABC):
    """Summary 任务基类"""

    def __init__(self):
        self.mode = MODE

    @abstractmethod
    def generate_summary(self):
        """生成 summary"""
        pass

    def log_info(self, message):
        """记录信息日志"""
        logger.info(f"[{self.mode}] {message}")


class RoutineCoverageJob(BaseCoverageJob):
    """Routine 模式的 Coverage 任务"""

    def execute(self):
        self.log_info("Starting routine coverage")
        print("routine coverage")
        self.log_info("Routine coverage completed")


class CommitCoverageJob(BaseCoverageJob):
    """Commit 模式的 Coverage 任务"""

    def execute(self):
        self.log_info("Starting commit coverage")
        print("commit coverage")
        self.log_info("Commit coverage completed")


class LocalCoverageJob(BaseCoverageJob):
    """Local 模式的 Coverage 任务"""

    def execute(self):
        self.log_info("Starting local coverage")
        print("local coverage")
        self.log_info("Local coverage completed")


class CoverageJobFactory:
    """Coverage Job 工厂类"""

    @staticmethod
    def create_job(mode):
        """根据 mode 创建对应的 job 实例"""
        jobs = {
            "routine": RoutineCoverageJob,
            "commit": CommitCoverageJob,
            "local": LocalCoverageJob,
        }

        job_class = jobs.get(mode)
        if job_class is None:
            raise ValueError(f"Unknown mode: {mode}")

        return job_class()


def main():
    """主函数入口"""
    try:
        job = CoverageJobFactory.create_job(MODE)
        job.execute()
    except ValueError as e:
        logger.error(str(e))
        print("unknown mode")
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()
"
